∀ {S : CategoryTheory.ShortComplex.{0, 1} Etingof.Problem7_8_5_Complex}
  (hS : CategoryTheory.ShortComplex.ShortExact.{0, 1} S) (i j : Int)
  (hij : ComplexShape.Rel.{0} (ComplexShape.up.{0} Int) i j),
  And
    (CategoryTheory.ShortComplex.Exact.{0, 1}
      (CategoryTheory.ShortComplex.mk.{0, 1} (CategoryTheory.ShortComplex.ShortExact.δ.{0, 1, 0} hS i j hij)
        (HomologicalComplex.homologyMap.{0, 1, 0} (CategoryTheory.ShortComplex.f.{0, 1} S) j) ⋯))
    (And
      (CategoryTheory.ShortComplex.Exact.{0, 1}
        (CategoryTheory.ShortComplex.mk.{0, 1}
          (HomologicalComplex.homologyMap.{0, 1, 0} (CategoryTheory.ShortComplex.f.{0, 1} S) i)
          (HomologicalComplex.homologyMap.{0, 1, 0} (CategoryTheory.ShortComplex.g.{0, 1} S) i) ⋯))
      (CategoryTheory.ShortComplex.Exact.{0, 1}
        (CategoryTheory.ShortComplex.mk.{0, 1}
          (HomologicalComplex.homologyMap.{0, 1, 0} (CategoryTheory.ShortComplex.g.{0, 1} S) i)
          (CategoryTheory.ShortComplex.ShortExact.δ.{0, 1, 0} hS i j hij) ⋯)))

∀ {D : Etingof.Problem7_8_5_Complex} (C : Etingof.Problem7_8_5_Subcomplex D) (i j : Int)
  (hij : ComplexShape.Rel.{0} (ComplexShape.up.{0} Int) i j),
  And
    (CategoryTheory.ShortComplex.Exact.{0, 1}
      (CategoryTheory.ShortComplex.mk.{0, 1} (C.concreteConnecting i j hij)
        (HomologicalComplex.homologyMap.{0, 1, 0} (CategoryTheory.ShortComplex.f.{0, 1} C.shortComplex) j) ⋯))
    (And
      (CategoryTheory.ShortComplex.Exact.{0, 1}
        (CategoryTheory.ShortComplex.mk.{0, 1}
          (HomologicalComplex.homologyMap.{0, 1, 0} (CategoryTheory.ShortComplex.f.{0, 1} C.shortComplex) i)
          (HomologicalComplex.homologyMap.{0, 1, 0} (CategoryTheory.ShortComplex.g.{0, 1} C.shortComplex) i) ⋯))
      (CategoryTheory.ShortComplex.Exact.{0, 1}
        (CategoryTheory.ShortComplex.mk.{0, 1}
          (HomologicalComplex.homologyMap.{0, 1, 0} (CategoryTheory.ShortComplex.g.{0, 1} C.shortComplex) i)
          (C.concreteConnecting i j hij) ⋯)))
